package com.muswall.app.ui

import android.app.AlertDialog
import android.app.WallpaperManager
import android.content.Intent
import android.net.Uri
import android.os.Bundle
import android.text.InputType
import android.widget.EditText
import android.widget.LinearLayout
import android.widget.SeekBar
import android.widget.TextView
import androidx.activity.result.contract.ActivityResultContracts
import androidx.appcompat.app.AppCompatActivity
import androidx.appcompat.app.AppCompatDelegate
import androidx.appcompat.widget.SwitchCompat
import com.muswall.app.R
import com.muswall.app.data.PreferencesManager
import com.muswall.app.service.MediaNotificationListenerService
import com.muswall.app.wallpaper.MusicWallpaperService
import com.muswall.app.wallpaper.WallpaperHelper
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.cancel
import kotlinx.coroutines.launch

class SettingsActivity : AppCompatActivity() {
    private lateinit var prefs: PreferencesManager; private lateinit var wallpaperHelper: WallpaperHelper; private val ioScope=CoroutineScope(SupervisorJob()+Dispatchers.Main.immediate); private var originalTarget=WallpaperManager.FLAG_SYSTEM; private var currentDialogSliderTarget:((String,Int)->Unit)?=null
    private val customPhotoPicker=registerForActivityResult(ActivityResultContracts.OpenDocument()){uri->if(uri!=null){try{contentResolver.takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION)}catch(_:Throwable){};prefs.customPhotoUri=uri.toString();prefs.photoSource=PreferencesManager.PHOTO_CUSTOM;updatePhotoLabels()}}
    private val originalWallpaperPicker=registerForActivityResult(ActivityResultContracts.OpenDocument()){uri->if(uri!=null){try{contentResolver.takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION)}catch(_:Throwable){};ioScope.launch{val ok=wallpaperHelper.setOriginalFromUri(uri,originalTarget);ToastCompat.show(this@SettingsActivity,if(ok)"Original wallpaper saved" else "Could not save wallpaper")}}}
    override fun onCreate(savedInstanceState:Bundle?){super.onCreate(savedInstanceState);prefs=PreferencesManager.getInstance(this);wallpaperHelper=WallpaperHelper(this);setContentView(R.layout.activity_settings);findViewById<TextView>(R.id.back).setOnClickListener{finish()};findViewById<TextView>(R.id.themeRow).setOnClickListener{chooseTheme()};findViewById<TextView>(R.id.languageRow).setOnClickListener{chooseLanguage()};findViewById<TextView>(R.id.backgroundRow).setOnClickListener{chooseBackgroundMode()};findViewById<TextView>(R.id.backgroundColorRow).setOnClickListener{chooseColor(false)};findViewById<TextView>(R.id.gradientColorRow).setOnClickListener{chooseColor(true)};findViewById<TextView>(R.id.accentColorRow).setOnClickListener{chooseAccentColor()};findViewById<TextView>(R.id.resolutionRow).setOnClickListener{chooseWallpaperQuality()};findViewById<TextView>(R.id.effectRow).setOnClickListener{chooseEffect()};findViewById<TextView>(R.id.blurRow).setOnClickListener{chooseBlurAndDepth()};findViewById<TextView>(R.id.lyricsPositionRow).setOnClickListener{chooseLyricsPosition()};findViewById<TextView>(R.id.bassPositionRow).setOnClickListener{chooseBassPosition()};findViewById<TextView>(R.id.widgetRow).setOnClickListener{chooseWidgetStyle()};findViewById<TextView>(R.id.restoreHomeRow).setOnClickListener{chooseOriginalWallpaper(WallpaperManager.FLAG_SYSTEM)};findViewById<TextView>(R.id.restoreLockRow).setOnClickListener{chooseOriginalWallpaper(WallpaperManager.FLAG_LOCK)};findViewById<TextView>(R.id.timingRow).setOnClickListener{chooseTiming()};findViewById<TextView>(R.id.permissionsRow).setOnClickListener{XiaomiHelper.openNotificationListenerSettings(this)};findViewById<TextView>(R.id.serviceRow).setOnClickListener{XiaomiHelper.openNotificationListenerSettings(this)};findViewById<TextView>(R.id.compatibilityRow).setOnClickListener{ToastCompat.show(this,"POCO/MIUI mode uses the Android live-wallpaper engine and the system Lock-screen destination. Disable battery restrictions for MusWall.")};findViewById<TextView>(R.id.feedbackRow).setOnClickListener{runCatching{startActivity(Intent(Intent.ACTION_SENDTO,Uri.parse("mailto:")))}};findViewById<TextView>(R.id.faqRow).setOnClickListener{AlertDialog.Builder(this).setTitle("MusWall FAQ").setMessage("Lyrics use timestamped metadata first and LRCLIB synced lyrics as a fallback. Original language is the default. Translation is optional. Position, line count, size and colors are applied immediately.").setPositiveButton("OK",null).show()};findViewById<TextView>(R.id.updateRow).setOnClickListener{AlertDialog.Builder(this).setTitle("MusWall").setMessage("Version 4.0").setPositiveButton("OK",null).show()};findViewById<TextView>(R.id.photoSourceRow).setOnClickListener{choosePhotoSource()};findViewById<TextView>(R.id.customPhotoRow).setOnClickListener{customPhotoPicker.launch(arrayOf("image/*"))};findViewById<SwitchCompat>(R.id.lyricsSwitch).apply{showText=false;isChecked=prefs.showLyrics;setOnCheckedChangeListener{_,v->prefs.showLyrics=v;refreshLive()}};findViewById<SwitchCompat>(R.id.bassSwitch).apply{showText=false;isChecked=prefs.bassEnabled;setOnCheckedChangeListener{_,v->prefs.bassEnabled=v;refreshLive()}};findViewById<SwitchCompat>(R.id.photoFallbackSwitch).apply{showText=false;isChecked=prefs.photoFallback;setOnCheckedChangeListener{_,v->prefs.photoFallback=v}};findViewById<SwitchCompat>(R.id.effectsRestore).apply{showText=false;isChecked=prefs.effect!=PreferencesManager.EFFECT_BLUR;setOnCheckedChangeListener{_,v->if(!v)prefs.effect=PreferencesManager.EFFECT_BLUR}};updatePhotoLabels();updateWallpaperQualityLabel();updateLyricsLabel();updateBassLabel();updateEffectLabel();updateBlurLabel()}
    private fun refreshLive(){sendBroadcast(Intent(MusicWallpaperService.ACTION_REFRESH).setPackage(packageName));sendBroadcast(Intent(MediaNotificationListenerService.ACTION_SETTINGS_CHANGED).setPackage(packageName))}
    private fun updatePhotoLabels(){findViewById<TextView>(R.id.photoSourceRow).text="Music photo\n${prefs.photoSource}"};private fun choosePhotoSource(){val labels=arrayOf("Automatic","Album artwork","Track artwork","Display icon","Notification artwork","Custom image");val values=arrayOf(PreferencesManager.PHOTO_AUTO,PreferencesManager.PHOTO_ALBUM,PreferencesManager.PHOTO_ART,PreferencesManager.PHOTO_DISPLAY_ICON,PreferencesManager.PHOTO_NOTIFICATION,PreferencesManager.PHOTO_CUSTOM);AlertDialog.Builder(this).setTitle("Music photo source").setItems(labels){_,i->if(values[i]==PreferencesManager.PHOTO_CUSTOM&&prefs.customPhotoUri.isBlank())customPhotoPicker.launch(arrayOf("image/*"))else{prefs.photoSource=values[i];updatePhotoLabels();refreshLive()}}.show()}
    private fun chooseEffect(){val labels=arrayOf("Cover","Blur","Square","Cover Color","CD","Kaleidoscope","Pulse","Float");val values=arrayOf(PreferencesManager.EFFECT_COVER,PreferencesManager.EFFECT_BLUR,PreferencesManager.EFFECT_SQUARE,PreferencesManager.EFFECT_COVER_COLOR,PreferencesManager.EFFECT_CD,PreferencesManager.EFFECT_KALEIDOSCOPE,PreferencesManager.EFFECT_PULSE,PreferencesManager.EFFECT_FLOAT);AlertDialog.Builder(this).setTitle("Wallpaper effect").setItems(labels){_,i->prefs.effect=values[i];updateEffectLabel();refreshLive()}.show()}
    private fun chooseBlurAndDepth(){val root=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL};val type=TextView(this).apply{text="Blur type: ${prefs.blurType}";setOnClickListener{chooseBlurType(this)}};val r=slider("Blur radius",prefs.blurRadius,0,80);val d=slider("Darkness",prefs.darkness);val s=slider("Artwork scale",prefs.artScale,20,120);listOf(type,r.label,r.seek,d.label,d.seek,s.label,s.seek).forEach{root.addView(it)};AlertDialog.Builder(this).setTitle("Blur & depth").setView(root).setPositiveButton("Done"){_,_->prefs.blurRadius=r.value();prefs.darkness=d.value();prefs.artScale=s.value();refreshLive()}.setNegativeButton("Close",null).show()}
    private fun chooseBlurType(label:TextView){val labels=arrayOf("Gaussian","Solid/Box","Motion","Glass","Radial");val values=arrayOf(PreferencesManager.BLUR_GAUSSIAN,PreferencesManager.BLUR_SOLID,PreferencesManager.BLUR_MOTION,PreferencesManager.BLUR_GLASS,PreferencesManager.BLUR_RADIAL);AlertDialog.Builder(this).setTitle("Blur algorithm").setItems(labels){_,i->prefs.blurType=values[i];label.text="Blur type: ${values[i]}";refreshLive()}.show()}
    private fun chooseLyricsPosition(){currentDialogSliderTarget={n,v->when(n){"Horizontal position"->prefs.lyricsX=v;"Vertical position"->prefs.lyricsY=v;"Text width"->prefs.lyricsWidth=v;"Text size"->prefs.lyricsSize=v;"Visible lyric lines"->prefs.lyricsLines=v}};val root=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL};val x=slider("Horizontal position",prefs.lyricsX);val y=slider("Vertical position",prefs.lyricsY);val w=slider("Text width",prefs.lyricsWidth,20);val s=slider("Text size",prefs.lyricsSize,10,72);val l=slider("Visible lyric lines",prefs.lyricsLines,1,6);listOf(x,y,w,s,l).forEach{root.addView(it.label);root.addView(it.seek)};val mode=TextView(this).apply{text="Color mode: ${colorModeName(prefs.lyricsColorMode)}";setOnClickListener{chooseColorMode("Lyrics",true,this)}};val colors=TextView(this).apply{text="Colors: ${prefs.lyricsColor} • ${prefs.lyricsColor2} • ${prefs.lyricsColor3}";setOnClickListener{chooseThreeColors(true,this)}};val lang=TextView(this).apply{text="Language: ${languageName(prefs.lyricsLanguage)}";setOnClickListener{chooseLyricsLanguage(this)}};root.addView(mode);root.addView(colors);root.addView(lang);AlertDialog.Builder(this).setTitle("Lyrics — live position, style & language").setView(root).setPositiveButton("Done"){_,_->prefs.lyricsX=x.value();prefs.lyricsY=y.value();prefs.lyricsWidth=w.value();prefs.lyricsSize=s.value();prefs.lyricsLines=l.value();updateLyricsLabel();refreshLive()}.setNegativeButton("Close",null).show()}
    private fun chooseBassPosition(){currentDialogSliderTarget={n,v->when(n){"Horizontal position"->prefs.bassX=v;"Vertical position"->prefs.bassY=v;"Width"->prefs.bassWidth=v;"Bar height"->prefs.bassHeight=v;"Sensitivity"->prefs.bassSensitivity=v}};val root=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL};val x=slider("Horizontal position",prefs.bassX);val y=slider("Vertical position",prefs.bassY);val w=slider("Width",prefs.bassWidth,20);val h=slider("Bar height",prefs.bassHeight,2,30);val se=slider("Sensitivity",prefs.bassSensitivity);listOf(x,y,w,h,se).forEach{root.addView(it.label);root.addView(it.seek)};val mode=TextView(this).apply{text="Color mode: ${colorModeName(prefs.bassColorMode)}";setOnClickListener{chooseColorMode("Bass",false,this)}};val colors=TextView(this).apply{text="Colors: ${prefs.bassColor} • ${prefs.bassColor2} • ${prefs.bassColor3}";setOnClickListener{chooseThreeColors(false,this)}};root.addView(mode);root.addView(colors);AlertDialog.Builder(this).setTitle("Bass — live position & color").setView(root).setPositiveButton("Done"){_,_->prefs.bassX=x.value();prefs.bassY=y.value();prefs.bassWidth=w.value();prefs.bassHeight=h.value();prefs.bassSensitivity=se.value();updateBassLabel();refreshLive()}.setNegativeButton("Close",null).show()}
    private data class Slider(val label:TextView,val seek:SeekBar,val min:Int,val max:Int){fun value()=seek.progress+min}
    private fun slider(name:String,value:Int,min:Int=0,max:Int=100):Slider{val label=TextView(this).apply{text="$name: $value"};val seek=SeekBar(this).apply{this.max=max-min;progress=(value-min).coerceIn(0,max-min);setOnSeekBarChangeListener(object:SeekBar.OnSeekBarChangeListener{override fun onProgressChanged(s:SeekBar?,p:Int,fromUser:Boolean){val v=p+min;label.text="$name: $v";if(fromUser){currentDialogSliderTarget?.invoke(name,v);refreshLive()}};override fun onStartTrackingTouch(s:SeekBar?){ };override fun onStopTrackingTouch(s:SeekBar?){ }})};return Slider(label,seek,min,max)}
    private fun chooseColorMode(title:String,lyrics:Boolean,label:TextView){val names=arrayOf("Single color","Gradient / double color","Double color","Rainbow / colorful");val vals=arrayOf(PreferencesManager.COLOR_SINGLE,PreferencesManager.COLOR_GRADIENT,PreferencesManager.COLOR_DOUBLE,PreferencesManager.COLOR_RAINBOW);AlertDialog.Builder(this).setTitle("$title color style").setItems(names){_,i->if(lyrics)prefs.lyricsColorMode=vals[i]else prefs.bassColorMode=vals[i];label.text="Color mode: ${colorModeName(vals[i])}";refreshLive()}.show()}
    private fun chooseThreeColors(lyrics:Boolean,label:TextView){val a=if(lyrics)prefs.lyricsColor else prefs.bassColor;val b=if(lyrics)prefs.lyricsColor2 else prefs.bassColor2;val c=if(lyrics)prefs.lyricsColor3 else prefs.bassColor3;val root=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL};val e1=EditText(this).apply{hint="Primary #RRGGBB";setText(a)};val e2=EditText(this).apply{hint="Secondary #RRGGBB";setText(b)};val e3=EditText(this).apply{hint="Third #RRGGBB";setText(c)};root.addView(e1);root.addView(e2);root.addView(e3);AlertDialog.Builder(this).setTitle("Custom colors").setView(root).setPositiveButton("Save"){_,_->if(lyrics){prefs.lyricsColor=validHex(e1.text.toString(),a);prefs.lyricsColor2=validHex(e2.text.toString(),b);prefs.lyricsColor3=validHex(e3.text.toString(),c)}else{prefs.bassColor=validHex(e1.text.toString(),a);prefs.bassColor2=validHex(e2.text.toString(),b);prefs.bassColor3=validHex(e3.text.toString(),c)};refreshLive()}.setNegativeButton("Cancel",null).show()}
    private fun validHex(v:String,f:String)=runCatching{android.graphics.Color.parseColor(v.trim());v.trim()}.getOrDefault(f);private fun colorModeName(v:String)=when(v){PreferencesManager.COLOR_GRADIENT->"Gradient";PreferencesManager.COLOR_DOUBLE->"Double";PreferencesManager.COLOR_RAINBOW->"Rainbow";else->"Single"};private fun languageName(c:String)=when(c.lowercase()){"original","auto"->"Original";"en"->"English";"hi"->"Hindi";"es"->"Spanish";"fr"->"French";"de"->"German";"ja"->"Japanese";"ko"->"Korean";"zh"->"Chinese";"ar"->"Arabic";"ru"->"Russian";"pt"->"Portuguese";"bn"->"Bengali";"ta"->"Tamil";"te"->"Telugu";"mr"->"Marathi";else->c}
    private fun chooseLyricsLanguage(label:TextView){val names=arrayOf("Original (default)","English","Hindi","Spanish","French","German","Japanese","Korean","Chinese","Arabic","Russian","Portuguese","Bengali","Tamil","Telugu","Marathi","Custom code");val codes=arrayOf("original","en","hi","es","fr","de","ja","ko","zh","ar","ru","pt","bn","ta","te","mr","custom");AlertDialog.Builder(this).setTitle("Lyrics language").setItems(names){_,i->if(codes[i]=="custom"){val e=EditText(this).apply{hint="Language code e.g. tr, ur, it"};AlertDialog.Builder(this).setTitle("Translation language code").setView(e).setPositiveButton("Save"){_,_->prefs.lyricsLanguage=e.text.toString().trim().ifBlank{"original"};label.text="Language: ${languageName(prefs.lyricsLanguage)}";refreshLive()}.show()}else{prefs.lyricsLanguage=codes[i];label.text="Language: ${names[i]}";refreshLive()}}.show()}
    private fun chooseWidgetStyle(){AlertDialog.Builder(this).setTitle("Music widget style").setItems(arrayOf("MusWall Card","Glass","Minimal")){_,i->prefs.widgetStyle=i;sendBroadcast(Intent(MediaNotificationListenerService.ACTION_WIDGET_CHANGED).setPackage(packageName))}.show()}
    private fun updateLyricsLabel(){findViewById<TextView>(R.id.lyricsPositionRow).text="Lyrics position\nX ${prefs.lyricsX}% • Y ${prefs.lyricsY}% • width ${prefs.lyricsWidth}% • size ${prefs.lyricsSize} • ${colorModeName(prefs.lyricsColorMode)} • ${languageName(prefs.lyricsLanguage)}"};private fun updateBassLabel(){findViewById<TextView>(R.id.bassPositionRow).text="Bass position\nX ${prefs.bassX}% • Y ${prefs.bassY}% • width ${prefs.bassWidth}% • height ${prefs.bassHeight} • ${colorModeName(prefs.bassColorMode)}"};private fun updateEffectLabel(){findViewById<TextView>(R.id.effectRow).text="Visual effect\n${prefs.effect.replace('_',' ').replaceFirstChar{it.uppercase()}}"};private fun updateBlurLabel(){findViewById<TextView>(R.id.blurRow).text="Blur & depth\n${prefs.blurType} • radius ${prefs.blurRadius} • darkness ${prefs.darkness} • scale ${prefs.artScale}"}
    private fun chooseWallpaperQuality(){val labels=arrayOf("Original","Auto (device resolution)","4K","8K");val vals=arrayOf(PreferencesManager.WALLPAPER_QUALITY_ORIGINAL,PreferencesManager.WALLPAPER_QUALITY_AUTO,PreferencesManager.WALLPAPER_QUALITY_4K,PreferencesManager.WALLPAPER_QUALITY_8K);AlertDialog.Builder(this).setTitle("Wallpaper quality").setSingleChoiceItems(labels,vals.indexOf(prefs.wallpaperQuality).coerceAtLeast(0)){d,i->prefs.wallpaperQuality=vals[i];updateWallpaperQualityLabel();d.dismiss();refreshLive()}.show()};private fun updateWallpaperQualityLabel(){val label=when(prefs.wallpaperQuality){PreferencesManager.WALLPAPER_QUALITY_ORIGINAL->"Original artwork";PreferencesManager.WALLPAPER_QUALITY_4K->"4K • aspect adapted";PreferencesManager.WALLPAPER_QUALITY_8K->"8K • aspect adapted";else->"Auto • device resolution"};findViewById<TextView>(R.id.resolutionRow).text="Wallpaper quality\n$label"};private fun chooseTheme(){AlertDialog.Builder(this).setTitle("Theme").setItems(arrayOf("Follow System","Light","Dark")){_,i->AppCompatDelegate.setDefaultNightMode(when(i){1->AppCompatDelegate.MODE_NIGHT_NO;2->AppCompatDelegate.MODE_NIGHT_YES;else->AppCompatDelegate.MODE_NIGHT_FOLLOW_SYSTEM})}.show()};private fun chooseLanguage(){AlertDialog.Builder(this).setTitle("Language").setMessage("Interface follows Android. Lyrics language is configured separately.").setPositiveButton("OK",null).show()};private fun chooseBackgroundMode(){AlertDialog.Builder(this).setTitle("Wallpaper background").setItems(arrayOf("Album artwork","Solid","Gradient","Auto color")){_,i->prefs.backgroundMode=when(i){1->PreferencesManager.BACKGROUND_COLOR;2->PreferencesManager.BACKGROUND_GRADIENT;3->PreferencesManager.BACKGROUND_AUTO;else->PreferencesManager.BACKGROUND_ART};refreshLive()}.show()};private fun chooseColor(second:Boolean){val c=arrayOf("#111111","#F7F7F7","#5E2CA5","#174EA6","#176B3A","#8B1E2D","#B85C00");AlertDialog.Builder(this).setTitle("Color").setItems(c){_,i->if(second)prefs.backgroundColor2=c[i]else prefs.backgroundColor=c[i];refreshLive()}.show()};private fun chooseAccentColor(){val c=arrayOf("#7C00FF","#00B8D9","#36C95F","#4285F4","#E91E63","#FFFFFF");AlertDialog.Builder(this).setTitle("Accent").setItems(c){_,i->prefs.accentColor=c[i];refreshLive()}.show()};private fun chooseOriginalWallpaper(which:Int){originalTarget=which;originalWallpaperPicker.launch(arrayOf("image/*"))};private fun chooseTiming(){AlertDialog.Builder(this).setTitle("Restore timing").setItems(arrayOf("Immediately","5 seconds","10 seconds","30 seconds")){_,i->prefs.restoreDelay=intArrayOf(0,5,10,30)[i]}.show()};override fun onDestroy(){ioScope.cancel();super.onDestroy()}
    object ToastCompat{fun show(c:android.content.Context,m:String){android.widget.Toast.makeText(c,m,android.widget.Toast.LENGTH_LONG).show()}}
}
